<?php
namespace qqworld_collector\module\collect_item; use qqworld_collector\lib; class post_link extends lib { var $guid; var $excluded_url = false; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-' . $this->guid, array($this, 'filter'), 10, 7 ); add_filter( 'qqworld-collector-collecting-engine-collect-item-after-filter-' . $this->guid, array($this, 'after_filter'), 10, 6 ); } public function check_excluded_url($item, $settings) { if (!$this->excluded_url) { if (isset($settings['excluded-url']) && !empty($settings['excluded-url'])) { $this->excluded_url = explode("\n", $settings['excluded-url']); foreach ($this->excluded_url as &$ex_url) { $ex_url = trim($ex_url); $ex_url = preg_replace('/^https?/i', '', $ex_url); } $this->excluded_url = array_filter($this->excluded_url, array($this, 'is_not_empty')); } } if (!empty($this->excluded_url)) { foreach ($this->excluded_url as $excluded_url) { if (strstr($item, $excluded_url) != FALSE) { $item .= '(disallowed:'.__('Excluded by collection settings', $this->text_domain).')'; break; } } } return $item; } public function filter($items, $args, $source_link, $html, $download_args, $settings, $mode) { if (!empty($items)) { foreach ($items as &$item) { $item = stripslashes($item); if (empty($item)) $item .= '(disallowed:'.__('No post link were collected', $this->text_domain).')'; $item = $this->check_excluded_url($item, $settings); } } else { $items = array('(disallowed:'.__('No post link were collected', $this->text_domain).')'); } return $items; } public function after_filter($items, $args, $source_link, $html, $settings, $mode) { if (!empty($items) && !preg_match('/\(disallowed:[^\)]*\)/i', $items)) $items = apply_filters( 'qqworld-collector-convert-relative-url-to-absolute-url', $items, $source_link ); return $items; } } ?>